<?php
declare(strict_types=1);
require_once __DIR__.'/course-store.php';require_once __DIR__.'/game.php';
function eqc_course(PDO $p,string $id,bool $admin=false): array {$c=hub_q($p,'SELECT * FROM eqc_courses WHERE id=?'.($admin?'':' AND published=1'),[$id])->fetch();if(!$c)fail(404,'Không tìm thấy giáo trình đã xuất bản.');return $c;}
function eqc_lesson(PDO $p,string $id,bool $admin=false): array {$l=hub_q($p,'SELECT l.*,u.course_id,u.title AS unit_title,c.level FROM eqc_lessons l JOIN eqc_units u ON u.id=l.unit_id JOIN eqc_courses c ON c.id=u.course_id WHERE l.id=?'.($admin?'':' AND l.published=1 AND u.published=1 AND c.published=1'),[$id])->fetch();if(!$l)fail(404,'Không tìm thấy bài học.');return $l;}
function eqc_detail(PDO $p,int $uid,string $course): array {
 $c=eqc_course($p,$course);unset($c['final_json']);$units=hub_q($p,'SELECT id,title,position FROM eqc_units WHERE course_id=? AND published=1 ORDER BY position,id',[$course])->fetchAll();$total=0;$done=0;
 foreach($units as &$unit){$ls=hub_q($p,'SELECT l.id,l.title,l.position,p.score,p.total,p.passed FROM eqc_lessons l LEFT JOIN eqc_progress p ON p.target_id=l.id AND p.user_id=? AND p.kind=\'lesson\' WHERE l.unit_id=? AND l.published=1 ORDER BY l.position,l.id',[$uid,$unit['id']])->fetchAll();$unit['lessons']=$ls;$total+=count($ls);$done+=count(array_filter($ls,fn($l)=>(bool)$l['passed']));$unit['exam']=hub_q($p,"SELECT score,total,passed FROM eqc_progress WHERE user_id=? AND target_id=? AND kind='unit'",[$uid,$unit['id']])->fetch()?:null;}unset($unit);
 $c['language_code']=$c['language_code']?:((str_starts_with($course,'chinese-')?'zh-CN':'en-US'));$c['units']=$units;$c['completed']=$done;$c['total']=$total;$c['percent']=$total?(int)round($done/$total*100):0;$c['final']=hub_q($p,"SELECT score,total,passed FROM eqc_progress WHERE user_id=? AND target_id=? AND kind='final'",[$uid,$course])->fetch()?:null;$c['certificate']=hub_q($p,'SELECT * FROM eqc_certificates WHERE user_id=? AND course_id=?',[$uid,$course])->fetch()?:null;
 $c['next_lesson']=null;foreach($units as $unit)foreach($unit['lessons'] as $l)if(!$l['passed']&&$c['next_lesson']===null)$c['next_lesson']=['id'=>$l['id'],'title'=>$l['title'],'reason'=>$l['total']?'Ôn lại bài chưa đạt 70%.':'Bài tiếp theo trong lộ trình.'];
 $c['active_run']=hub_q($p,'SELECT id,target_id,kind FROM eqc_runs WHERE user_id=? AND course_id=? AND finished=0 AND started_at>? ORDER BY started_at DESC LIMIT 1',[$uid,$course,time()-3600])->fetch()?:null;return $c;
}
function eqc_public_question(array $q): array {unset($q['answer'],$q['answers'],$q['explanation']);return $q;}
function eqc_run(PDO $p,int $uid,string $id,bool $lock=false): array {$r=hub_q($p,'SELECT * FROM eqc_runs WHERE id=? AND user_id=?'.($lock&&$p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id,$uid])->fetch();if(!$r)fail(404,'Không tìm thấy lượt học của bạn.');$r['state']=json_decode($r['state'],true,64,JSON_THROW_ON_ERROR);return $r;}
function eqc_public_run(array $r): array {$s=$r['state'];return ['id'=>$r['id'],'course_id'=>$r['course_id'],'target_id'=>$r['target_id'],'kind'=>$r['kind'],'index'=>$s['index'],'total'=>count($s['questions']),'score'=>$s['correct'],'finished'=>(bool)$r['finished'],'question'=>$r['finished']?null:eqc_public_question($s['questions'][$s['index']]),'result'=>$s['result']??null];}
function eqc_grade(array $q,mixed $answer): bool {
 if(in_array($q['type'],['choice','listen'],true)){if(!is_int($answer)||!isset($q['options'][$answer]))fail(422,'Lựa chọn chưa hợp lệ.');return $answer===$q['answer'];}
 if($q['type']==='match'){if(!is_array($answer)||!array_is_list($answer)||count($answer)!==count($q['left']))fail(422,'Cần ghép đủ các cặp.');$sorted=$answer;sort($sorted);if($sorted!==range(0,count($q['left'])-1))fail(422,'Mỗi nghĩa chỉ được ghép một lần.');return $answer===$q['answer'];}
 if(!is_string($answer)||strlen($answer)>1000)fail(422,'Câu trả lời chưa hợp lệ.');$expected=$q['type']==='fill'?$q['answers']:[$q['answer']];foreach($expected as $e)if(game_normalize($answer)===game_normalize($e))return true;return false;
}
function eqc_finish(PDO $p,int $uid,array $r,array &$state): array {
 $score=$state['correct'];$total=count($state['questions']);$passed=$score/$total>=.7;$kind=$r['kind'];$target=$r['target_id'];
 if($kind==='placement')return ['score'=>$score,'total'=>$total,'passed'=>$passed,'xp'=>0,'recommendation'=>$score/$total>=.8?'Bạn đã nắm khá vững kiến thức Starter. Ôn nhanh và làm kiểm tra chương để xác nhận.':'Bắt đầu English Starter từ bảng chữ cái, rồi học lần lượt để củng cố nền tảng.','scope'=>'Chẩn đoán kiến thức Starter, không xác định CEFR chính thức.'];
 try{hub_q($p,'INSERT INTO eqc_progress(user_id,target_id,kind) VALUES (?,?,?)',[$uid,$target,$kind]);}catch(PDOException $e){if((string)$e->getCode()!=='23000')throw $e;}
 $old=hub_q($p,'SELECT * FROM eqc_progress WHERE user_id=? AND target_id=? AND kind=?'.($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$uid,$target,$kind])->fetch();$better=(int)$old['total']===0||$score/$total>=(int)$old['score']/max(1,(int)$old['total']);$xp=$passed&&!(int)$old['passed']?($kind==='lesson'?50:($kind==='unit'?30:100)):0;
 hub_q($p,'UPDATE eqc_progress SET score=?,total=?,passed=?,completed_at=? WHERE user_id=? AND target_id=? AND kind=?',[$better?$score:(int)$old['score'],$better?$total:(int)$old['total'],($passed||(int)$old['passed'])?1:0,$old['completed_at']?:($passed?time():null),$uid,$target,$kind]);
 try{hub_q($p,'INSERT INTO eq_progress(user_id,state) VALUES (?,?)',[$uid,json_encode(game_initial())]);}catch(PDOException $e){if((string)$e->getCode()!=='23000')throw $e;}
 $raw=hub_q($p,'SELECT state FROM eq_progress WHERE user_id=?'.($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$uid])->fetchColumn();$progress=json_decode($raw,true,512,JSON_THROW_ON_ERROR);$progress['xp']+=$xp;if($passed&&!in_array('course-'.$kind.'-'.$target,$progress['completed'],true))$progress['completed'][]='course-'.$kind.'-'.$target;$title=hub_q($p,'SELECT title FROM '.($kind==='lesson'?'eqc_lessons':($kind==='unit'?'eqc_units':'eqc_courses')).' WHERE id=?',[$target])->fetchColumn()?:$target;$day=date('Y-m-d');if(!in_array($day,$progress['days'],true))$progress['days'][]=$day;$progress['history']=array_slice([['title'=>'Giáo trình · '.$title,'score'=>$score,'total'=>$total,'date'=>date('c')],...$progress['history']],0,100);$progress['daily']??=[];$progress['daily'][$day]=($progress['daily'][$day]??0)+$total;$progress['daily']=array_slice($progress['daily'],-90,null,true);hub_q($p,'UPDATE eq_progress SET state=? WHERE user_id=?',[json_encode($progress,JSON_UNESCAPED_UNICODE),$uid]);
 $cert=null;if($kind==='final'&&$passed){$c=eqc_detail($p,$uid,$r['course_id']);$unitsPassed=!count(array_filter($c['units'],fn($u)=>empty($u['exam']['passed'])));if($c['completed']===$c['total']&&$c['total']>0&&$unitsPassed){$u=hub_q($p,'SELECT display_name FROM eq_users WHERE id=?',[$uid])->fetch();$existing=hub_q($p,'SELECT id FROM eqc_certificates WHERE user_id=? AND course_id=?',[$uid,$r['course_id']])->fetchColumn();if(!$existing){$cert=bin2hex(random_bytes(16));hub_q($p,'INSERT INTO eqc_certificates(id,user_id,course_id,course_title,display_name,score,issued_at) VALUES (?,?,?,?,?,?,?)',[$cert,$uid,$r['course_id'],$c['title'],$u['display_name'],(int)round($score/$total*100),time()]);}else $cert=$existing;}}
 return ['score'=>$score,'total'=>$total,'passed'=>$passed,'xp'=>$xp,'certificate'=>$cert];
}
function eq_courses(PDO $p,int $uid,array $config,string $op,array $in): never {
 if($op==='course_list'){$rows=hub_q($p,'SELECT id FROM eqc_courses WHERE published=1 ORDER BY position,id')->fetchAll();$courses=[];foreach($rows as $r)$courses[]=eqc_detail($p,$uid,$r['id']);reply(200,['ok'=>true,'courses'=>$courses]);}
 if($op==='course_detail')reply(200,['ok'=>true,'course'=>eqc_detail($p,$uid,hub_text($in,'id',60))]);
 if($op==='course_lesson'){$l=eqc_lesson($p,hub_text($in,'id',60));$content=json_decode($l['content_json'],true,64,JSON_THROW_ON_ERROR);reply(200,['ok'=>true,'lesson'=>['id'=>$l['id'],'title'=>$l['title'],'course_id'=>$l['course_id'],'unit_id'=>$l['unit_id'],'unit_title'=>$l['unit_title'],'level'=>$l['level'],'content'=>$content,'exercise_count'=>count(json_decode($l['exercises_json'],true))]]);}
 if($op==='course_begin'){
  limit_attempts($p,'coursebegin:'.$uid,30,3600);$kind=field($in,'kind');$id=hub_text($in,'id',60);$course='';$qs=[];
  if($kind==='placement'){$c=eqc_course($p,$id);$course=$id;$qs=json_decode($c['final_json'],true,64,JSON_THROW_ON_ERROR);}
  elseif($kind==='lesson'){$l=eqc_lesson($p,$id);$course=$l['course_id'];$qs=json_decode($l['exercises_json'],true,64,JSON_THROW_ON_ERROR);}
  elseif($kind==='unit'){$u=hub_q($p,'SELECT * FROM eqc_units WHERE id=? AND published=1',[$id])->fetch();if(!$u)fail(404,'Không tìm thấy chương.');$c=eqc_detail($p,$uid,$u['course_id']);$unit=null;foreach($c['units'] as $x)if($x['id']===$id)$unit=$x;if(!$unit||count(array_filter($unit['lessons'],fn($l)=>!$l['passed'])))fail(409,'Hoàn thành các bài trong chương trước khi kiểm tra.');$course=$u['course_id'];$qs=json_decode($u['exam_json'],true,64,JSON_THROW_ON_ERROR);}
  elseif($kind==='final'){$c=eqc_detail($p,$uid,$id);if($c['completed']!==$c['total']||count(array_filter($c['units'],fn($u)=>empty($u['exam']['passed']))))fail(409,'Hoàn thành bài học và kiểm tra chương trước khi thi cuối khóa.');$course=$id;$qs=json_decode(eqc_course($p,$id)['final_json'],true,64,JSON_THROW_ON_ERROR);}
  else fail(422,'Loại bài chưa hợp lệ.');eqc_exercises($qs);$run=bin2hex(random_bytes(16));$state=['questions'=>$qs,'index'=>0,'correct'=>0,'events'=>[]];hub_q($p,'INSERT INTO eqc_runs(id,user_id,course_id,target_id,kind,state,started_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$run,$uid,$course,$id,$kind,json_encode($state,JSON_UNESCAPED_UNICODE),time(),time()]);reply(200,['ok'=>true,'run'=>eqc_public_run(eqc_run($p,$uid,$run))]);
 }
 if($op==='course_run')reply(200,['ok'=>true,'run'=>eqc_public_run(eqc_run($p,$uid,hub_text($in,'run',40)))]);
 if($op==='course_answer'){
  $id=hub_text($in,'run',40);$event=hub_text($in,'event',64);if(!preg_match('/^[a-zA-Z0-9-]{16,64}$/D',$event))fail(422,'Mã gửi chưa hợp lệ.');$p->beginTransaction();try{
   $r=eqc_run($p,$uid,$id,true);$state=$r['state'];if(isset($state['events'][$event])){$p->commit();reply(200,['ok'=>true,'run'=>eqc_public_run($r),'feedback'=>$state['events'][$event]]);}
   if($r['finished']||time()-(int)$r['started_at']>3600){$p->rollBack();fail(409,'Lượt làm bài đã kết thúc hoặc quá một giờ.');}
   if(($in['index']??null)!==$state['index']){$p->rollBack();fail(409,'Câu hỏi đã thay đổi. Hãy tải lại lượt làm bài.');}
   $q=$state['questions'][$state['index']];$correct=eqc_grade($q,$in['answer']??null);$feedback=['correct'=>$correct,'explanation'=>$q['explanation']];$state['correct']+=(int)$correct;$state['index']++;$state['events'][$event]=$feedback;$finished=$state['index']===count($state['questions']);if($finished)$state['result']=eqc_finish($p,$uid,$r,$state);
   hub_q($p,'UPDATE eqc_runs SET state=?,finished=?,updated_at=? WHERE id=?',[json_encode($state,JSON_UNESCAPED_UNICODE),$finished?1:0,time(),$id]);$p->commit();reply(200,['ok'=>true,'run'=>eqc_public_run(eqc_run($p,$uid,$id)),'feedback'=>$feedback]);
  }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
 }
 if($op==='course_vocab_mark'){
  $l=eqc_lesson($p,hub_text($in,'lesson',60));$words=json_decode($l['content_json'],true)['vocabulary'];$i=$in['index']??-1;if(!is_int($i)||!isset($words[$i]))fail(422,'Từ chưa hợp lệ.');$old=hub_q($p,'SELECT * FROM eqc_reviews WHERE user_id=? AND lesson_id=? AND word_index=?',[$uid,$l['id'],$i])->fetch();$interval=!empty($in['known'])?min(30,max(1,(int)($old['interval_days']??0)*2)):0;
  if($old)hub_q($p,'UPDATE eqc_reviews SET due_at=?,interval_days=? WHERE user_id=? AND lesson_id=? AND word_index=?',[time()+$interval*86400,$interval,$uid,$l['id'],$i]);else hub_q($p,'INSERT INTO eqc_reviews(user_id,lesson_id,word_index,due_at,interval_days) VALUES (?,?,?,?,?)',[$uid,$l['id'],$i,time()+$interval*86400,$interval]);reply(200,['ok'=>true]);
 }
 if($op==='course_reviews'){$out=[];foreach(hub_q($p,'SELECT r.*,l.title,l.content_json FROM eqc_reviews r JOIN eqc_lessons l ON l.id=r.lesson_id JOIN eqc_units u ON u.id=l.unit_id JOIN eqc_courses c ON c.id=u.course_id WHERE r.user_id=? AND r.due_at<=? AND l.published=1 AND u.published=1 AND c.published=1 ORDER BY r.due_at LIMIT 100',[$uid,time()])->fetchAll() as $r){$r['word']=json_decode($r['content_json'],true)['vocabulary'][$r['word_index']]??null;unset($r['content_json']);$out[]=$r;}reply(200,['ok'=>true,'reviews'=>$out]);}
 if($op==='course_certificates')reply(200,['ok'=>true,'certificates'=>hub_q($p,'SELECT * FROM eqc_certificates WHERE user_id=? ORDER BY issued_at DESC',[$uid])->fetchAll()]);
 if($op==='course_tutor'){
  $l=eqc_lesson($p,hub_text($in,'lesson',60));$content=json_decode($l['content_json'],true);$run=field($in,'run');$active=$run!==''&&!eqc_run($p,$uid,$run)['finished'];
  if($active)reply(200,['ok'=>true,'source'=>'guide','answer'=>'Hãy tự làm câu đang hiển thị. Gợi ý kiến thức: '.$content['grammar']['rule'].' Sau khi nộp, hệ thống sẽ giải thích đáp án.']);
  require_once __DIR__.'/hub-ai.php';$course=eqc_course($p,$l['course_id']);$targetLanguage=match($course['language_code']??'en-US'){'zh-CN'=>'Mandarin Chinese','vi-VN'=>'Vietnamese','math'=>'Mathematics',default=>'English'};$ctx=['course'=>$course['title'],'unit'=>$l['unit_title'],'lesson'=>$l['title'],'level'=>$l['level'],'learner_level'=>hub_profile($p,$uid)['level'],'learning_goal'=>hub_profile($p,$uid)['goal'],'knowledge'=>$content['explanation'],'examples'=>$content['examples'],'language'=>'vi','target_language'=>$targetLanguage];$res=hub_ai($p,$uid,$config,'course_tutor',hub_text($in,'question',3000),$ctx);reply(200,['ok'=>true]+$res+['answer'=>$content['explanation']."\n\n".$content['summary']]);
 }
 if(str_starts_with($op,'course_admin_')){eqc_admin($p,$uid,$op,$in);}
 fail(404,'Không tìm thấy chức năng giáo trình.');
}
function eqc_admin(PDO $p,int $uid,string $op,array $in): never {
 if(hub_profile($p,$uid)['role']!=='admin')fail(403,'Chỉ admin được quản lý giáo trình.');
 if($op==='course_admin_list')reply(200,['ok'=>true,'courses'=>hub_q($p,'SELECT id,title,published,level,skill,position FROM eqc_courses ORDER BY position,id')->fetchAll()]);
 if($op==='course_admin_get'){$c=eqc_course($p,hub_text($in,'id',60),true);$c['final']=json_decode($c['final_json'],true);unset($c['final_json']);$units=hub_q($p,'SELECT * FROM eqc_units WHERE course_id=? ORDER BY position,id',[$c['id']])->fetchAll();foreach($units as &$u){$u['exam']=json_decode($u['exam_json'],true);unset($u['exam_json']);$ls=hub_q($p,'SELECT * FROM eqc_lessons WHERE unit_id=? ORDER BY position,id',[$u['id']])->fetchAll();foreach($ls as &$l){$l['content']=json_decode($l['content_json'],true);$l['exercises']=json_decode($l['exercises_json'],true);unset($l['content_json'],$l['exercises_json']);}unset($l);$u['lessons']=$ls;}unset($u);$c['units']=$units;$learners=(int)hub_q($p,'SELECT COUNT(DISTINCT p.user_id) FROM eqc_progress p WHERE p.target_id=? OR p.target_id IN(SELECT id FROM eqc_units WHERE course_id=?) OR p.target_id IN(SELECT l.id FROM eqc_lessons l JOIN eqc_units u ON u.id=l.unit_id WHERE u.course_id=?)',[$c['id'],$c['id'],$c['id']])->fetchColumn();$certs=(int)hub_q($p,'SELECT COUNT(*) FROM eqc_certificates WHERE course_id=?',[$c['id']])->fetchColumn();reply(200,['ok'=>true,'course'=>$c,'stats'=>['learners'=>$learners,'certificates'=>$certs,'completion_percent'=>$learners?round($certs/$learners*100):0]]);}
 if($op==='course_admin_visibility'){$id=hub_text($in,'id',60);hub_q($p,'UPDATE eqc_courses SET published=? WHERE id=?',[!empty($in['published'])?1:0,$id]);hub_audit($p,$uid,'course_visibility',0,$id);reply(200,['ok'=>true]);}
 if($op==='course_admin_save'){
  $kind=field($in,'kind');$d=$in['data']??null;if(!is_array($d))fail(422,'Dữ liệu JSON chưa hợp lệ.');$id=eqc_slug((string)($d['id']??''));$title=hub_text($d,'title',160);$pos=$d['position']??1;if(!is_int($pos)||$pos<1||$pos>999)fail(422,'Thứ tự chưa hợp lệ.');
  if($kind==='course'){$levels=['Pre-A1','A0','A1','A2','B1','B2','C1','C2','IELTS','HSK 1','HSK 2','HSK 3','HSK 4','HSK 5','HSK 6','Lớp 1–3','Lớp 4–6','Lớp 7–9','Lớp 10–12','Olympiad'];if(!in_array($d['level']??'',$levels,true))fail(422,'Trình độ chưa hợp lệ.');$language=(string)($d['language_code']??(str_starts_with($id,'chinese-')?'zh-CN':'en-US'));if(!in_array($language,['en-US','en','zh-CN','vi-VN','math'],true))fail(422,'Ngôn ngữ giáo trình chưa hợp lệ.');eqc_upsert($p,'eqc_courses',$id,['title'=>$title,'description'=>hub_text($d,'description',4000),'level'=>$d['level'],'language_code'=>$language,'skill'=>hub_text($d,'skill',30),'position'=>$pos,'published'=>!empty($d['published'])?1:0,'final_json'=>json_encode(eqc_exercises($d['final']??[]),JSON_UNESCAPED_UNICODE)]);}
  elseif($kind==='unit'){eqc_course($p,(string)($d['course_id']??''),true);eqc_upsert($p,'eqc_units',$id,['course_id'=>$d['course_id'],'title'=>$title,'position'=>$pos,'published'=>!empty($d['published'])?1:0,'exam_json'=>json_encode(eqc_exercises($d['exam']??[]),JSON_UNESCAPED_UNICODE)]);}
  elseif($kind==='lesson'){
   if(!hub_q($p,'SELECT 1 FROM eqc_units WHERE id=?',[$d['unit_id']??''])->fetchColumn())fail(422,'Chương chưa tồn tại.');$content=$d['content']??null;if(!is_array($content))fail(422,'Thiếu nội dung.');foreach(['objectives','explanation','vocabulary','grammar','dialogue','reading','speaking','summary','review'] as $key)if(empty($content[$key]))fail(422,'Thiếu nội dung '.$key);
   foreach($content['media_ids']??[] as $fid){if(!is_int($fid))fail(422,'Media ID chưa hợp lệ.');hub_owned_file($p,$uid,$fid);}
   $p->beginTransaction();try{eqc_upsert($p,'eqc_lessons',$id,['unit_id'=>$d['unit_id'],'title'=>$title,'position'=>$pos,'published'=>!empty($d['published'])?1:0,'content_json'=>json_encode($content,JSON_UNESCAPED_UNICODE),'exercises_json'=>json_encode(eqc_exercises($d['exercises']??[]),JSON_UNESCAPED_UNICODE)]);hub_q($p,'DELETE FROM eqc_media WHERE lesson_id=?',[$id]);foreach(array_unique($content['media_ids']??[]) as $fid)hub_q($p,'INSERT INTO eqc_media(lesson_id,file_id) VALUES (?,?)',[$id,$fid]);$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
  }else fail(422,'Loại nội dung chưa hợp lệ.');hub_audit($p,$uid,'course_content_saved',0,$kind.':'.$id);reply(200,['ok'=>true]);
 }
 fail(404,'Không tìm thấy chức năng quản trị giáo trình.');
}
